#if TITLE_FOUNDATION
import Foundation
#endif

enum TitlePreview {
    static let inputSize = 34
    static let outputSize = 34

    static func render(_ input: UnsafeRawBufferPointer, into output: UnsafeMutableRawBufferPointer) -> Bool {
        guard input.count == inputSize, input[0] == 1 else { return false }
        let end = 2 + Int(input[1])
        guard end <= inputSize else { return false }
        for offset in end ..< inputSize {
            if input[offset] != 0 { return false }
        }
        let title = UnsafeRawBufferPointer(rebasing: input[2 ..< end])
#if TITLE_FOUNDATION || TITLE_STRING
        guard let decoded = String(validating: title, as: UTF8.self) else { return false }
#if TITLE_FOUNDATION
        let trimmed = decoded.trimmingCharacters(in: .whitespacesAndNewlines)
#else
        let scalars = decoded.unicodeScalars
        var first = scalars.startIndex
        var last = scalars.endIndex
        while first < last, edgeWhitespace(scalars[first].value) {
            scalars.formIndex(after: &first)
        }
        while first < last {
            let previous = scalars.index(before: last)
            guard edgeWhitespace(scalars[previous].value) else { break }
            last = previous
        }
        let trimmed = String(scalars[first ..< last])
#endif
        let utf8 = trimmed.utf8
        guard !utf8.isEmpty else { return false }
        output[0] = UInt8(utf8.count)
        output[1] = UInt8(trimmed.unicodeScalars.count)
        for offset in 2 ..< outputSize { output[offset] = 0 }
        var offset = 2
        for byte in utf8 {
            output[offset] = byte
            offset += 1
        }
#else
        var first = 0
        var last = title.count
        while first < last, edgeWhitespace(UInt32(title[first])) { first += 1 }
        while first < last, edgeWhitespace(UInt32(title[last - 1])) { last -= 1 }
        guard first < last else { return false }

        // Reject overlong, surrogate, out-of-range and incomplete UTF-8 before touching the frame.
        var offset = first
        var scalarCount: UInt8 = 0
        while offset < last {
            let lead = title[offset]
            let width: Int
            if lead < 0x80 { width = 1 }
            else if lead >= 0xC2 && lead <= 0xDF { width = 2 }
            else if lead >= 0xE0 && lead <= 0xEF { width = 3 }
            else if lead >= 0xF0 && lead <= 0xF4 { width = 4 }
            else { return false }
            guard offset + width <= last else { return false }
            if width > 1 {
                let next = title[offset + 1]
                if (lead == 0xE0 && next < 0xA0) || (lead == 0xED && next > 0x9F)
                    || (lead == 0xF0 && next < 0x90) || (lead == 0xF4 && next > 0x8F) { return false }
                for index in 1 ..< width {
                    guard title[offset + index] & 0xC0 == 0x80 else { return false }
                }
            }
            offset += width
            scalarCount += 1
        }
        output[0] = UInt8(last - first)
        output[1] = scalarCount
        for index in 2 ..< outputSize { output[index] = 0 }
        for index in first ..< last { output[2 + index - first] = title[index] }
#endif
        return true
    }

    // The compact projection trims only ASCII edge whitespace (HT through CR, plus SP).
    private static func edgeWhitespace(_ value: UInt32) -> Bool {
        value == 0x20 || (value >= 0x09 && value <= 0x0D)
    }
}

