import Foundation

private struct Case: Decodable {
    let name: String
    let input: Data
    let accepts: Bool
    let frame: Data
}

private struct Observation: Encodable {
    let name: String
    let accepted: Bool
    let frame: Data
    let fuel: UInt64?
}

private struct Receipt: Encodable {
    let initial: Data
    let events: [Observation]
    let retiredAndReclaimed: Bool
}

private struct ReplayFailure: Error { let reason: String }

@main private enum TitleHost {
    static func main() throws {
        let args = CommandLine.arguments
        let cases = try JSONDecoder().decode([Case].self, from: Data(contentsOf: URL(fileURLWithPath: args[1])))
        let observations: [Observation]
        let initial: Data
#if TITLE_OWNED_HOST
        let path = OwnedTask(try Data(contentsOf: URL(fileURLWithPath: args[2])), measureComponents: false)
        try path.open()
        initial = try path.frame()
        observations = try cases.map { test in
            let accepted = try path.activate(Array(test.input))
            let frame = try path.frame()
            guard path.fuel > 0, path.fuel <= 1_000_000 else {
                throw ReplayFailure(reason: "\(test.name): invalid owned-VM fuel")
            }
            return try observe(test, accepted: accepted, frame: frame, fuel: path.fuel)
        }
        try path.closeAndCheckReclamation(initialFrame: initial)
#else
        var frame = Data(count: TitlePreview.outputSize)
        initial = frame
        observations = try cases.map { test in
            let accepted = test.input.withUnsafeBytes { input in
                frame.withUnsafeMutableBytes { TitlePreview.render(input, into: $0) }
            }
            return try observe(test, accepted: accepted, frame: frame, fuel: nil)
        }
#endif
        guard initial == Data(count: 34) else { throw ReplayFailure(reason: "dirty initial frame") }
#if TITLE_OWNED_HOST
        let retiredAndReclaimed = true
#else
        let retiredAndReclaimed = false
#endif
        let data = try JSONEncoder().encode(Receipt(initial: initial, events: observations,
                                                   retiredAndReclaimed: retiredAndReclaimed))
        print(String(decoding: data, as: UTF8.self))
    }

    private static func observe(_ test: Case, accepted: Bool, frame: Data, fuel: UInt64?) throws -> Observation {
        guard accepted == test.accepts, frame == test.frame else {
            throw ReplayFailure(reason: "\(test.name): accepted=\(accepted), frame=\(frame.base64EncodedString())")
        }
        return Observation(name: test.name, accepted: accepted, frame: frame, fuel: fuel)
    }
}
